#include "gtest/gtest.h"
#include "fims_json.hpp"
#include <string>
#include "test_stubs.hpp"

namespace {
// JsonParser_EscapeString
// IO correctness
TEST(JsonParser_EscapeString, EscapesQuotesAndBackslashes) {
  using fims::JsonParser;

  // Test that quotes and backslashes are escaped.
  EXPECT_EQ(JsonParser::EscapeString("survey \"A\"\\x"),
            "survey \\\"A\\\"\\\\x");

  // Test that ordinary text, including spaces and JSON punctuation, is
  // unchanged.
  EXPECT_EQ(JsonParser::EscapeString("north, {east}: [1]"),
            "north, {east}: [1]");
}

TEST(JsonParser_EscapeString, RoundTripsThroughFormatAndParse) {
  using fims::JsonParser;

  // Test that each name written with EscapeString() and formatted with
  // PrettyFormatJSON() parses back to the original name.
  const std::string names[] = {"survey one", "survey \"A\"\\x",
                               "north, {east}: [1]", "ends with \\",
                               "tab\there"};
  JsonParser parser;
  for (const std::string& name : names) {
    std::string json = "{ \"fleet\" : \"" + JsonParser::EscapeString(name) +
                       "\" , \"n\" : 1 }";
    auto parsed = parser.Parse(JsonParser::PrettyFormatJSON(json));
    EXPECT_EQ(parsed.GetObject()["fleet"].GetString(), name);
  }
}

// Edge handling
TEST(JsonParser_EscapeString, EscapesControlCharacters) {
  using fims::JsonParser;

  // Test that newlines, returns, and tabs use their short escapes and other
  // control characters use \u escapes.
  EXPECT_EQ(JsonParser::EscapeString("a\nb\rc\td"), "a\\nb\\rc\\td");
  EXPECT_EQ(JsonParser::EscapeString(std::string("x\x01y")), "x\\u0001y");

  // Test that an empty string stays empty.
  EXPECT_EQ(JsonParser::EscapeString(""), "");
}

// Error handling
// No built-in errors to test.
}  // namespace
